def compute(vars):
    offered_square_feet = vars["v1"]
    total_leased_square_feet = vars["v2"]

    if total_leased_square_feet == 0:
        return None

    percentage = offered_square_feet / total_leased_square_feet * 100

    return {
        "value": percentage,
        "trace": {
            "offered_square_feet": offered_square_feet,
            "total_leased_square_feet": total_leased_square_feet,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage",
            },
        },
    }
